 */";s:65:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespaceUses";O:30:"PHPStan\Analyser\NamespaceUses":3:{s:9:"namespace";s:30:"App\Modules\Analytics\Services";s:4:"uses";a:10:{s:13:"profitability";s:42:"App\Modules\Finance\Services\Profitability";s:16:"industrytemplate";s:44:"App\Modules\Industry\Models\IndustryTemplate";s:13:"kpidefinition";s:41:"App\Modules\Industry\Models\KpiDefinition";s:23:"industrytemplateservice";s:53:"App\Modules\Industry\Services\IndustryTemplateService";s:10:"stockquery";s:41:"App\Modules\Inventory\Services\StockQuery";s:16:"correctiveaction";s:40:"App\Modules\Loss\Models\CorrectiveAction";s:12:"lossincident";s:36:"App\Modules\Loss\Models\LossIncident";s:15:"settingsservice";s:43:"App\Modules\Shared\Services\SettingsService";s:15:"carboninterface";s:22:"Carbon\CarbonInterface";s:2:"db";s:29:"Illuminate\Support\Facades\DB";}s:9:"constUses";a:0:{}}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:1;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:4:{i:0;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:9:"SUPPORTED";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:86:"['expiry_exposure', 'capa_overdue', 'open_count', 'gross_margin_pct', 'shrinkage_pct']";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀attributes";a:0:{}}}s:66:"␀PHPStan\Depen