rtedPhpDocNode":2:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:1243:"/**
 * Makes a create (or any change) safe to send twice. The app sends `Idempotency-Key: <a fresh UUID per action>`; the first
 * request runs and its successful answer is remembered under (user, key); a repeat — the network dropped the reply, or the
 * offline queue replayed — gets that same answer back, marked `Idempotent-Replayed: true`, and nothing runs again.
 *
 *  - `idempotent:required` refuses a request without a key (creates); plain `idempotent` uses a key when one is sent.
 *  - The same key with a **different** request (other path, body or company) is an error, not a silent replay.
 *  - Two requests with one key arriving together: the database's unique key lets exactly one in; the other is told to wait
 *    (409 request_in_progress, Retry-After) and, once the first finishes, gets its answer.
 *  - Only a **successful** answer is kept. Anything else (a refusal, a validation error, a crash) releases the key, so the
 *    person can fix the problem and send the same action again.
 *  - A request that started but never finished (the server died) is presumed dead after `idempotency_stale_seconds` and the
 *    key may then be taken over. Keys expire after `idempotency_ttl_hours` (`api:prune` removes them).
 */";s:65:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespaceUses";O:30:"PHPStan\Analyser\NamespaceUses":3:{s:9:"namespace";s:31:"App\Modules\Api\Http\Middleware";s:4:"uses";a:11:{s:4:"user";s:15:"App\Models\User";s:12:"apiexception";s:36:"App\Modules\Api\Support\ApiException";s:13:"tenantcontext";s:40:"App\Modules\Shared\Tenancy\TenantContext";s:7:"closure";s:7:"Closure";s:34:"uniqueconstraintviolationexception";s:54:"Illuminate\Database\UniqueConstraintViolationException";s:12:"jsonresponse";s:28:"Illuminate\Http\JsonResponse";s:7:"request";s:23:"Illuminate\Http\Request";s:2:"db";s:29:"Illuminate\Support\Facades\DB";s:8:"stdclass";s:8:"stdClass";s:8:"response";s:41:"Symfony\Component\HttpFoundation\Response";s:9:"throwable";s:9:"Throwable";}s:9:"constUses";a:0:{}}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:2:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀r