     * The invoice for an order — made now if it has not been, otherwise the one that exists. Returns null for an order that cannot be invoiced
     * (not approved, or cancelled).
     */";s:65:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespaceUses";r:6;}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:38:"?App\Modules\Sales\Models\SalesInvoice";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:1:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:5:"order";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:39:"App\Modules\Sales\Models\SalesOrder|int";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}}s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀attributes";a:0:{}}}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀attributes";a:0:{}}}a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:47:"App\Modules\Sales\Services\NetRevenueCalculator";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":2:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:1181:"/**
 * Net revenue, cost of goods sold, gross profit and margin for a period — FORMULAS.md §2, version 1. The only place these are worked out, so
 * the dashboard, the reports and the exports (Phase L6) cannot disagree.
 *
 *   gross_sales   = Σ gross amount of the lines of issued invoices dated in the period
 *   discounts     = Σ discount of those lines
 *   returns       = Σ taxable value of **approved** returns and credit notes dated in the period (a draft, pending or rejected one counts for nothing)
 *   net_revenue   = gross_sales − discounts − returns
 *   cogs          = Σ cost of those invoice lines − Σ cost of the returned lines
 *   gross_profit  = net_revenue − cogs
 *   margin_pct    = null when net_revenue is 0, else gross_profit ÷ net_revenue × 100 (2 decimals, half up)
 *
 * Tax is left out of every figure. A cancelled invoice counts for nothing. A line with no known cost adds nothing to the cost, and is counted in
 * `lines_without_cost` so a report can say its profit is not complete — a missing cost is never read as zero. Everything runs through the
 * tenant scopes, so a person sees the company and branches they work in.
 */";s:65:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespaceUses";O:30:"PHPStan\Analyser\NamespaceUses":3:{s:9:"namespace";s:26:"App\Modules\Sales\Services";s:4:"uses";a:5:{s:12:"salesinvoice";s:37:"App\Modules\Sales\Models\SalesInvoice";s:16:"salesinvoiceitem";s:41:"App\Modules\Sales\Models\SalesInvoiceItem";s:11:"salesreturn";s:36:"App\Modules\Sales\Models\SalesReturn";s:15:"salesreturnitem";s:40:"App\Modules\Sales\Models\SalesReturnItem";s:15:"carboninterface";s:22:"Carbon\CarbonInterface";}s:9:"constUses";a:0:{}}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:1;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:1:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:9:"forPeriod";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":2:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:217:"/**
